"""Tiny CSV line parser (no ``csv`` module dependency)."""


def split_csv(line: str) -> list[str]:
    """Split a single CSV line into fields.

    Fields may be wrapped in double quotes; inside quotes a comma is literal and a
    doubled quote (``""``) stands for a single quote character. The surrounding quotes
    are not part of the field value.
    """
    fields: list[str] = []
    field: list[str] = []
    in_quotes = False
    i = 0
    while i < len(line):
        char = line[i]
        if in_quotes:
            if char == '"':
                if i + 1 < len(line) and line[i + 1] == '"':
                    field.append('"')
                    i += 1
                else:
                    in_quotes = False
            else:
                field.append(char)
        elif char == ',':
            fields.append(''.join(field))
            field = []
        elif char == '"':
            in_quotes = True
        else:
            field.append(char)
        i += 1
    fields.append(''.join(field))
    return fields
